	forkPrompt: {
		owner: string;
		repo: string;
		intent: 'commit' | 'push';
		commit?: { summary: string; description: string };
	} | null;
	// Set when a checked-out branch's PR is observed transitioning unmerged →
	// merged, driving the "switch back to the default branch?" dialog. Cleared
